using System;using System.IO;using System.Collections.Generic;class ShortcutTests{static void Main(){string root=Path.Combine(Path.GetTempPath(),"BellShortcuts-"+Guid.NewGuid().ToString("N"));var written=new List<string>();string warning=ShortcutManager.Configure(root,"settings.exe",false,new[]{Path.Combine(root,"blockedDesktop"),Path.Combine(root,"OneDriveDesktop"),Path.Combine(root,"StartMenu"),root},(path,exe,home)=>{if(path.Contains("blockedDesktop"))throw new UnauthorizedAccessException("Desktop blocked");written.Add(path);});if(written.Count!=3||!warning.Contains("Desktop blocked"))throw new Exception("Nonfatal fallback failed");Console.WriteLine("PASS: blocked Desktop is nonfatal; redirected Desktop, Start menu and application-folder shortcuts continue.");}}
